// === Tab: mySketch ===
let particles = [];
let flock;

function setup() {
  createCanvas(800, 600);
  background('#f0ead6');

  flock = new Flock();

  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height);
    let particle = new Particle(x, y);
    flock.addParticle(particle);
  }
}

function draw() {
  background(240, 234, 214, 10);

  if (frameCount % 5 == 0) {
    var x = random(width);
    var y = random(height);
    var particle = new Particle(x, y);
    flock.addParticle(particle);
  }

  flock.update();
  flock.display();
  flock.removeDeadParticles();
}

function mouseDragged() {
  var particle = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  flock.addParticle(particle);
}

class Particle {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.velocity = createVector(random(-1, 1), random(-1, 1));
    this.acceleration = createVector();
    this.maxSpeed = 3;
    this.maxForce = 0.05;
    this.radius = 4;
    this.color = color(random(255), random(255), random(255), 80);
    this.lifespan = random(100, 300);
  }

  update() {
    this.position.add(this.velocity);
    this.velocity.add(this.acceleration);
    this.velocity.limit(this.maxSpeed);
    this.acceleration.mult(0);

    this.lifespan -= 1;
  }

  applyForce(force) {
    this.acceleration.add(force);
  }

  flock(particles) {
    let alignment = createVector();
    let cohesion = createVector();
    let separation = createVector();
    let perceptionRadius = 50;
    let total = 0;

    for (let other of particles) {
      let distance = this.position.dist(other.position);

      if (other != this && distance < perceptionRadius) {
        alignment.add(other.velocity);
        cohesion.add(other.position);

        let difference = p5.Vector.sub(this.position, other.position);
        difference.div(distance);
        separation.add(difference);

        total++;
      }
    }

    if (total > 0) {
      alignment.div(total);
      alignment.setMag(this.maxSpeed);
      alignment.sub(this.velocity);
      alignment.limit(this.maxForce);

      cohesion.div(total);
      cohesion.sub(this.position);
      cohesion.setMag(this.maxSpeed);
      cohesion.sub(this.velocity);
      cohesion.limit(this.maxForce);

      separation.div(total);
      separation.setMag(this.maxSpeed);
      separation.sub(this.velocity);
      separation.limit(this.maxForce);
    }

    this.applyForce(alignment);
    this.applyForce(cohesion);
    this.applyForce(separation);
  }

  display() {
    noStroke();
    fill(this.color);
    ellipse(this.position.x, this.position.y, this.radius * 2, this.radius * 2);
  }

  isDead() {
    return this.lifespan < 0;
  }
}

class Flock {
  constructor() {
    this.particles = [];
  }

  addParticle(particle) {
    this.particles.push(particle);
  }

  update() {
    for (let particle of this.particles) {
      particle.flock(this.particles);
      particle.update();
    }
  }

  display() {
    for (let particle of this.particles) {
      particle.display();
    }
  }

  removeDeadParticles() {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      if (this.particles[i].isDead()) {
        this.particles.splice(i, 1);
      }
    }
  }
}

